import {mountainBounds,mountainHalfWidth} from './mountain-layout.js';
import {makePanel} from './panels.js';
import {skiJumps,skiNetwork,resortRides,peakSummit,summit,middleSummit,ridgeBase,ridgeSummit,alpineShift} from './resort-layout.js';
const {minZ,maxZ,maxX}=mountainBounds,x=n=>300+n*260/maxX,z=n=>32+(n-alpineShift-minZ)*506/(maxZ-minZ);
const path=points=>points.map((p,i)=>`${i?'L':'M'}${x(p.x).toFixed(1)} ${z(p.z).toFixed(1)}`).join(' ');
const outline=[...Array.from({length:101},(_,i)=>{const localZ=minZ+i*(maxZ-minZ)/100;return{x:mountainHalfWidth(localZ),z:localZ+alpineShift};}),...Array.from({length:101},(_,i)=>{const localZ=maxZ-i*(maxZ-minZ)/100;return{x:-mountainHalfWidth(localZ),z:localZ+alpineShift};})];
const names={lift:'눈꽃 리프트',upperlift:'포레스트 리프트',ridgelift:'정상 연결 리프트',gondola:'구름정상 곤돌라'};
const panel=makePanel('ski-trail-map','설산 리조트',`<svg viewBox="0 0 600 580" role="img" aria-label="실제 경로를 기준으로 만든 다섯 슬로프와 곤돌라·리프트 지도"><defs><linearGradient id="trail-snow" x2="0" y2="1"><stop stop-color="#c7e9f5" stop-opacity=".12"/><stop offset="1" stop-color="#e6eeef" stop-opacity=".025"/></linearGradient></defs><path d="${path(outline)}Z" fill="url(#trail-snow)"/>${skiNetwork.map(r=>`<path data-course="${r.id}" d="${path(r.points)}" fill="none" stroke="${r.color}" stroke-width="5" stroke-linejoin="round" stroke-linecap="round"/>`).join('')}${Object.entries(resortRides).filter(([id])=>id!=='ski').map(([id,r])=>`<path d="${path(r.points.map(p=>({x:p[0],z:p[2]})))}" fill="none" stroke="${id==='gondola'?'#f4d69a':'#ecf2f5'}" stroke-width="2" stroke-dasharray="4 5"><title>${names[id]}</title></path>`).join('')}${[peakSummit,middleSummit,summit,ridgeBase,ridgeSummit].map(p=>`<circle cx="${x(p.x)}" cy="${z(p.z)}" r="4" fill="#fff2cf"/>`).join('')}${[[peakSummit,'구름정상 · '+Math.round(peakSummit.height)+'m','곤돌라 · 정상 리프트'],[middleSummit,'중간 쉼터','정상 리프트 환승'],[summit,'눈꽃 출발','초급 리프트']].map(([p,name,sub])=>`<text x="${x(p.x)-12}" y="${z(p.z)-21}" text-anchor="end">${name}<tspan x="${x(p.x)-12}" dy="22">${sub}</tspan></text>`).join('')}${skiJumps.map(j=>`<path d="M${x(j.x)-4} ${z(j.z)+3}l4 -7 4 7Z" fill="#fff0bd"><title>선택 점프대 · 옆길 통과 가능</title></path>`).join('')}<text x="300" y="559" text-anchor="middle">베이스 · 어묵 · 모닥불 · 료칸 연결</text><circle data-skier r="6" fill="#fff" stroke="#182c43" stroke-width="2"/>${skiNetwork.flatMap(r=>r.merges.map(m=>{const p=r.points.reduce((a,b)=>Math.abs(a.z-m.z)<Math.abs(b.z-m.z)?a:b);return`<circle cx="${x(p.x)}" cy="${z(p.z)}" r="5" fill="none" stroke="#edf6f6" stroke-width="1.5"/>`;})).join('')}</svg><div class="trail-map-legend">${skiNetwork.map(r=>`<button type="button" data-trail="${r.id}" aria-pressed="false"><i style="background:${r.color}"></i><span>${r.name}<small>${r.level} · ${(r.length/1000).toFixed(2)} km · 낙차 ${Math.round(r.drop)}m</small></span></button>`).join('')}</div><p class="trail-map-cables">금색 점선: 곤돌라 · 흰색 점선: 리프트</p>`);
panel.dialog.querySelectorAll('[data-trail]').forEach(button=>button.onclick=()=>{const active=button.getAttribute('aria-pressed')!=='true';panel.dialog.querySelectorAll('[data-trail]').forEach(b=>b.setAttribute('aria-pressed',String(active&&b===button)));panel.dialog.querySelectorAll('[data-course]').forEach(p=>{p.style.opacity=!active||p.dataset.course===button.dataset.trail?'1':'.25';});});
let frame=0;const marker=panel.dialog.querySelector('[data-skier]');
function update(){if(!panel.dialog.open){frame=0;return;}const p=window.labPlayerState;marker.setAttribute('visibility',!p||p.z> -50?'hidden':'visible');if(p){marker.setAttribute('cx',x(p.x));marker.setAttribute('cy',z(p.z));}frame=requestAnimationFrame(update);}
export function openSkiMap(){panel.open();if(!frame)frame=requestAnimationFrame(update);}
